"""Exhaustive EWS tests.

The band table below is declared *independently* of ews.py (same
thresholds, separately transcribed). All boundary cases are generated
programmatically from this test-local table: for every vital, every band
is probed at its low edge, its high edge, and one step beyond each edge
(where a neighbouring band exists), on both sides.
"""

import math

import pytest

from ews import EWS_TABLE, escalation, ews

# --- Independent transcription of the threshold bands -----------------
# Each vital: list of (low, high, score); None = unbounded side.
# STEP is the resolution used to probe just outside an edge.
TEST_TABLE = {
    "respiratory_rate": {
        "step": 1,
        "bands": [(0, 8, 3), (9, 11, 1), (12, 20, 0), (21, 24, 2), (25, None, 3)],
    },
    "spo2": {
        "step": 1,
        "bands": [(0, 91, 3), (92, 93, 2), (94, 95, 1), (96, None, 0)],
    },
    "temperature_c": {
        "step": 0.1,
        "bands": [
            (None, 35.0, 3),
            (35.1, 36.0, 1),
            (36.1, 38.0, 0),
            (38.1, 39.0, 1),
            (39.1, None, 2),
        ],
    },
    "sbp": {
        "step": 1,
        "bands": [(None, 90, 3), (91, 100, 2), (101, 110, 1), (111, 219, 0), (220, None, 3)],
    },
    "heart_rate": {
        "step": 1,
        "bands": [
            (None, 40, 3),
            (41, 50, 1),
            (51, 90, 0),
            (91, 110, 1),
            (111, 130, 2),
            (131, None, 3),
        ],
    },
}


def _probe_points(step, bands):
    """Yield (value, expected_score) covering every band edge both sides."""
    points = []
    for i, (low, high, score) in enumerate(bands):
        if low is not None:
            points.append((low, score))                      # inside: low edge
            if i > 0:
                prev_high = bands[i - 1][1]
                if low - step > prev_high or True:           # gap-free tables: still safe
                    pass
                points.append((round(low - step, 4), bands[i - 1][2]))  # outside: below low
        if high is not None:
            points.append((high, score))                     # inside: high edge
            if i + 1 < len(bands):
                points.append((round(high + step, 4), bands[i + 1][2]))  # outside: above high
    return points


def _cases():
    cases = []
    for vital, spec in TEST_TABLE.items():
        for value, expected in _probe_points(spec["step"], spec["bands"]):
            cases.append(pytest.param(vital, value, expected, id=f"{vital}={value}->{expected}"))
    return cases


@pytest.mark.parametrize("vital,value,expected", _cases())
def test_band_boundaries(vital, value, expected):
    total, breakdown = ews({vital: value})
    assert breakdown[vital] == expected
    assert total == expected


def test_table_in_engine_matches_test_transcription():
    for vital, spec in TEST_TABLE.items():
        normalized = [(lo if lo is not None else -math.inf,
                       hi if hi is not None else math.inf,
                       sc) for lo, hi, sc in spec["bands"]]
        assert EWS_TABLE[vital] == normalized


# --- Pinned whole-patient totals --------------------------------------

def test_pinned_patient_baseline_all_normal():
    vitals = {"respiratory_rate": 18, "spo2": 97, "temperature_c": 36.5, "sbp": 120, "heart_rate": 80}
    total, breakdown = ews(vitals)
    assert total == 0
    assert breakdown == {"respiratory_rate": 0, "spo2": 0, "temperature_c": 0, "sbp": 0, "heart_rate": 0}
    assert escalation(total) == "routine"


def test_pinned_patient_urgent():
    vitals = {"respiratory_rate": 22, "spo2": 93, "temperature_c": 38.5, "sbp": 95, "heart_rate": 105}
    total, breakdown = ews(vitals)
    # 2 + 2 + 1 + 2 + 1 = 8
    assert total == 8
    assert breakdown == {"respiratory_rate": 2, "spo2": 2, "temperature_c": 1, "sbp": 2, "heart_rate": 1}
    assert escalation(total) == "urgent"


def test_pinned_patient_elevated():
    vitals = {"respiratory_rate": 10, "spo2": 95, "temperature_c": 35.5, "sbp": 105, "heart_rate": 45}
    total, breakdown = ews(vitals)
    # 1 + 1 + 1 + 1 + 1 = 5
    assert total == 5
    assert breakdown == {"respiratory_rate": 1, "spo2": 1, "temperature_c": 1, "sbp": 1, "heart_rate": 1}
    assert escalation(total) == "elevated"


# --- Escalation tiers --------------------------------------------------

@pytest.mark.parametrize("total,level", [
    (0, "routine"), (4, "routine"),
    (5, "elevated"), (6, "elevated"),
    (7, "urgent"), (15, "urgent"),
])
def test_escalation_tiers(total, level):
    assert escalation(total) == level


def test_unknown_vital_rejected():
    with pytest.raises(KeyError):
        ews({"gcs": 15})

